package dev.emeth.companion;

import com.google.gson.JsonElement;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

/** The control-channel fixtures generated by the mind (mind/scripts/gen_control_fixtures.py). */
public final class Fixtures {
    private Fixtures() {}

    public static Path dir() {
        return Path.of(System.getProperty("emeth.fixtures", "../protocol/fixtures/control"));
    }

    public static JsonElement load(String name) {
        try {
            return JsonParser.parseString(Files.readString(dir().resolve(name), StandardCharsets.UTF_8));
        } catch (IOException e) {
            throw new IllegalStateException("missing fixture " + name + " in " + dir().toAbsolutePath() + " — run mind/scripts/gen_control_fixtures.py", e);
        }
    }
}
